Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

typedef pair<int,int> par;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int oo = (1<<29);

int ady[2*MAXM], flow[2*MAXM], cap[2*MAXM], nxt[2*MAXM];
int last[MAXN], now[MAXN], lev[MAXN], cola[MAXN];
int E, n, s, t, enq, deq;

void init_maxflow( int nn, int ss, int tt ){
    n = nn; s = ss; t = tt; E = 2;
    for( int i = 0; i <= n; i++ ) last[i] = 0;

    //cerr << "n = " << n << "  s = " << s << "  t = " << t << '\n';
}
void add_edge( int u, int v, int c ){
    ady[E] = v; flow[E] = 0; cap[E] = c; nxt[E] = last[u]; last[u] = E++;
    ady[E] = u; flow[E] = 0; cap[E] = 0; nxt[E] = last[v]; last[v] = E++;

    //cerr << "u = " << u << "  -->  v = " << v << "  cap = " << c << '\n';
}
bool bfs(){
    for( int u = 0; u <= n; u++ ) lev[u] = 0;
    enq = deq = 0;
    cola[enq++] = s;
    lev[s] = 1;
    while( deq < enq && !lev[t] ){
        int u = cola[deq++];
        for( int e = last[u]; e; e = nxt[e] ){
            int v = ady[e];
            if( !lev[v] && flow[e] < cap[e] ){
                lev[v] = lev[u] + 1;
                cola[enq++] = v;
            }
        }
    }
    return lev[t];
}
int dfs( int u, int F ){
    if( u == t ) return F;
    for( int e = now[u], f = 0; e; e = now[u] = nxt[e] ){
        int v = ady[e];
        if( lev[u] < lev[v] && flow[e] < cap[e] &&
            (f = dfs( v , min( F , cap[e] - flow[e] ) )) ){
            flow[e] += f;
            flow[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int max_flow(){
    int F = 0, f = 0;
    while( bfs() ){
        for( int i = 0; i <= n; i++ ) now[i] = last[i];
        while( (f = dfs( s , oo )) ) F += f;
    }
    return F;
}

int R;
string m1[MAXR];
string m2[MAXR];

int movI[] = { 0 , 1 , 0 , -1 };
int movJ[] = { 1 , 0 , -1 , 0 };

bool can_move( int i, int j ){
    return ( i >= 0 && j >= 0 && i < R && j < R && m1[i][j] != 'Y' && m1[i][j] != 'Z' );
}

int tim[2][MAXR][MAXR];

void bfs2( int i, int j, int cc ){
    for( int k = 0; k < R; k++ ){
        for( int l = 0; l < R; l++ ){
            tim[cc][k][l] = 0;
        }
    }

    tim[cc][i][j] = 1;
    queue<par> q;
    q.push( par( i , j ) );
    while( !q.empty() ){
        int i = q.front().first;
        int j = q.front().second;
        q.pop();

        if( cc == 1 && (tim[0][i][j] && tim[0][i][j] <= tim[1][i][j]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int ii = i + movI[k];
            int jj = j + movJ[k];

            if( can_move( ii , jj ) && !tim[cc][ii][jj] ){
                tim[cc][ii][jj] = tim[cc][i][j] + 1;
                q.push( par( ii , jj ) );
            }
        }
    }
}

int nod[2][MAXR][MAXR];


int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    //freopen("dat.txt","r",stdin);

    int T; cin >> R >> T;

    int zi = 0, zj = 0;

    int n = 0, s = 0, t = 0;

    for( int i = 0; i < R; i++ ){
        cin >> m1[i];
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] == 'Z' ){
                zi = i;
                zj = j;
            }
            else if( m1[i][j] != 'Y' ){
                n++;
                nod[0][i][j] = n;
            }
        }
    }

    for( int i = 0; i < R; i++ ){
        cin >> m2[i];
        for( int j = 0; j < R; j++ ){
            if( m2[i][j] != 'Y' && m2[i][j] != 'Z' ){
                n++;
                nod[1][i][j] = n;
            }
        }
    }

    n++;
    s = 0;
    t = n;

    init_maxflow( n , s , t );

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] != 'Z' && m1[i][j] != 'Y' ){
                add_edge( s , nod[0][i][j] , m1[i][j] - '0' );
                add_edge( nod[1][i][j] , t , m2[i][j] - '0' );
            }
        }
    }

    bfs2( zi , zj, 0 );

    //cerr << "T = " << T << '\n';

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] > '0' && m1[i][j] <= '9' ){
                bfs2( i , j , 1 );
                for( int ii = 0; ii < R; ii++ ){
                    for( int jj = 0; jj < R; jj++ ){
                        if( m2[ii][jj] > '0' && m2[ii][jj] <= '9' ){
                            if( tim[1][ii][jj] && (!tim[0][ii][jj] || tim[0][ii][jj] >= tim[1][ii][jj]) &&
                                tim[1][ii][jj]-1 <= T ){
                                add_edge( nod[0][i][j] , nod[1][ii][jj] , oo );
                                //cerr << "m1 = " << m1[i][j] << '\n';
                                //cerr << "i = " << i << " j = " << j << " ---> " << "ii = " << ii << " jj = " << jj << '\n';
                                //cerr << tim[1][ii][jj] << " - " << tim[0][ii][jj] << '\n';
                                //cerr << '\n';
                            }
                        }
                    }
                }
            }
        }
    }

    cout << max_flow() << '\n';
}

